INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1779145, 242879, 45047, '<td valign="top">I like the effect on this picture. The little thingy in this picture shows joy. This is a very interesting picture. Made to look this way on purpose or not, it doesn''t matter. Great job!</td>', 'I like the effect on this picture. The little thingy in this picture shows joy. This is a very interesting picture. Made to look this way on purpose or not, it doesn''t matter. Great job!', '2005-10-12 10:26:03.000000', NULL, 1),
(1779150, 241863, 15711, '<td valign="top">A bit contrived, but funny nonetheless. I think the checked tablecloth detracts from this - your eye gets caught up in it a bit. Great imagination.  Hope you enjoyed your lunch!</td>', 'A bit contrived, but funny nonetheless. I think the checked tablecloth detracts from this - your eye gets caught up in it a bit. Great imagination.  Hope you enjoyed your lunch!', '2005-10-12 10:28:16.000000', NULL, 1),
(1779151, 241789, 15711, '<td valign="top">Oops, wrong challenge.</td>', 'Oops, wrong challenge.', '2005-10-12 10:28:52.000000', NULL, 1),
(1779152, 241047, 45047, '<td valign="top">Okay, the holidays are coming and so, but still I find this idea a little bit used. You see those pumpkins everywhere.<br/>Dispite that fact, I think this picture is what this challenge was about. Showing human-like things. The doll in the background is a little bit out of focus, which makes this an even greater shot. The colors are,just about, perfect. The composition is great. One of my favourites in this challenge. Get''s a nine from me.</td>', 'Okay, the holidays are coming and so, but still I find this idea a little bit used. You see those pumpkins everywhere.Dispite that fact, I think this picture is what this challenge was about. Showing human-like things. The doll in the background is a little bit out of focus, which makes this an even greater shot. The colors are,just about, perfect. The composition is great. One of my favourites in this challenge. Get''s a nine from me.', '2005-10-12 10:29:10.000000', NULL, 1),
(1779155, 242709, 15711, '<td valign="top">Good lighting.  The pink ribbon is a nice touch. I''d give the dancer more negatie space and not have it dead center like a bulls eye.</td>', 'Good lighting.  The pink ribbon is a nice touch. I''d give the dancer more negatie space and not have it dead center like a bulls eye.', '2005-10-12 10:30:07.000000', NULL, 1),
(1779157, 242888, 15711, '<td valign="top">Love the springy green and water droplet effect.  Interesting and quite abstract.  I like it.</td>', 'Love the springy green and water droplet effect.  Interesting and quite abstract.  I like it.', '2005-10-12 10:30:41.000000', NULL, 1),
(1779160, 242982, 15711, '<td valign="top">HEE HEE. I like the idea of this. It is out of focus though. Bummer.</td>', 'HEE HEE. I like the idea of this. It is out of focus though. Bummer.', '2005-10-12 10:31:48.000000', NULL, 1),
(1779161, 242882, 45047, '<td valign="top">Very nice. You could think that the unused space on the top would be distracting, but I think it just embrases the emphasizes the impression the flower gives. I like this one. One of my favourites in this challenge.</td>', 'Very nice. You could think that the unused space on the top would be distracting, but I think it just embrases the emphasizes the impression the flower gives. I like this one. One of my favourites in this challenge.', '2005-10-12 10:32:05.000000', NULL, 1),
