(1781892, 243020, 43321, '<td valign="top">Geez!!  There could be kids watching!!  A+ for creativity.</td>', 'Geez!!  There could be kids watching!!  A+ for creativity.', '2005-10-13 11:32:42.000000', NULL, 1),
