(1787990, 243103, 36231, '<td valign="top">I like your angle and crop.  The "tear" of mustard adds a lot to your photo.I just wish your lighting was a little better. Good luck!</td>', 'I like your angle and crop.  The "tear" of mustard adds a lot to your photo.I just wish your lighting was a little better. Good luck!', '2005-10-16 17:32:49.000000', NULL, 1),
(1787991, 242381, 40155, '<td valign="top">Fantastic and sure to rate in the top ten!  10.</td>', 'Fantastic and sure to rate in the top ten!  10.', '2005-10-16 17:33:08.000000', NULL, 1),
(1787993, 242949, 43329, '<td valign="top">Sorry, I see this sculpture as being a personification by the sculptor, not the photographer. I also find the snails crawling in the hair make me feel uncomfortable, and the blurred lines (cobwebs?) in the foreground take away from the clarity of the image.</td>', 'Sorry, I see this sculpture as being a personification by the sculptor, not the photographer. I also find the snails crawling in the hair make me feel uncomfortable, and the blurred lines (cobwebs?) in the foreground take away from the clarity of the image.', '2005-10-16 17:33:44.000000', NULL, 1),
(1787994, 242705, 36231, '<td valign="top">Your colors and contrast work well.  I would have liked to see more of the umbrella, however, to get more of the emotion you were going for. Good luck!</td>', 'Your colors and contrast work well.  I would have liked to see more of the umbrella, however, to get more of the emotion you were going for. Good luck!', '2005-10-16 17:33:46.000000', NULL, 1),
(1787995, 242413, 40155, '<td valign="top">Sleeping I don''t see; weeping I do see.  The photo itself is beautiful.</td>', 'Sleeping I don''t see; weeping I do see.  The photo itself is beautiful.', '2005-10-16 17:34:11.000000', NULL, 1),
(1787997, 242608, 36231, '<td valign="top">This one made me chuckle.  I think the crop was too tight, would have been nice to see more of the other side and bottom.  The hat adds a nice touch. Good luck!</td>', 'This one made me chuckle.  I think the crop was too tight, would have been nice to see more of the other side and bottom.  The hat adds a nice touch. Good luck!', '2005-10-16 17:34:37.000000', NULL, 1),
(1787998, 243156, 40155, '<td valign="top">Wow, I like it.  You must have an observant eye.</td>', 'Wow, I like it.  You must have an observant eye.', '2005-10-16 17:34:50.000000', NULL, 1),
(1788000, 242207, 43329, '<td valign="top">Sorry, I see this sculpture as being a personification by the sculptor, not the photographer. Nice angle, though, and the colour of the rosary beads enhances the serene effect of the photograph by picking up the green tones in the background.</td>', 'Sorry, I see this sculpture as being a personification by the sculptor, not the photographer. Nice angle, though, and the colour of the rosary beads enhances the serene effect of the photograph by picking up the green tones in the background.', '2005-10-16 17:35:12.000000', NULL, 1),
(1788002, 241025, 36231, '<td valign="top">Interesting subject.  The crop takes more away from your photo than adds to it, however.  I would have liked to see more of the trees. Good luck!</td>', 'Interesting subject.  The crop takes more away from your photo than adds to it, however.  I would have liked to see more of the trees. Good luck!', '2005-10-16 17:35:28.000000', NULL, 1),
(1788004, 242867, 40155, '<td valign="top">Priceless and one to frame.  8.</td>', 'Priceless and one to frame.  8.', '2005-10-16 17:35:32.000000', NULL, 1),
(1788006, 243158, 43329, '<td valign="top">Sorry, I see this sculpture as being a personification by the sculptor, not the photographer. Nice closeup of the figurine, though.</td>', 'Sorry, I see this sculpture as being a personification by the sculptor, not the photographer. Nice closeup of the figurine, though.', '2005-10-16 17:35:48.000000', NULL, 1),
(1788007, 242027, 36231, '<td valign="top">Interesting subject with the glow of the fire. I am very worried that you threw this up in the air? :)  Hopw you didn''t make too much of a mess! Good luck!</td>', 'Interesting subject with the glow of the fire. I am very worried that you threw this up in the air? :)  Hopw you didn''t make too much of a mess! Good luck!', '2005-10-16 17:36:22.000000', NULL, 1),
(1788009, 242761, 40155, '<td valign="top">Great imagination.  I like the B &amp; W.  How did you leave the touch of green?  Did you remove some of the rbg channels?</td>', 'Great imagination.  I like the B & W.  How did you leave the touch of green?  Did you remove some of the rbg channels?', '2005-10-16 17:36:49.000000', NULL, 1),
(1788011, 241557, 43329, '<td valign="top">I cannot make a personification, either physical or emotional, out of this image.</td>', 'I cannot make a personification, either physical or emotional, out of this image.', '2005-10-16 17:37:00.000000', NULL, 1),
(1788012, 243005, 42602, '<td valign="top">Wow! That''s an incredible tree! I love the pose, but the focus is off.</td>', 'Wow! That''s an incredible tree! I love the pose, but the focus is off.', '2005-10-16 17:37:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1788013, 242742, 36231, '<td valign="top">Interesting subject.  I think a different angle or crop would have worked better for you. The colors are great. Good luck!</td>', 'Interesting subject.  I think a different angle or crop would have worked better for you. The colors are great. Good luck!', '2005-10-16 17:37:16.000000', NULL, 1),
(1788015, 241483, 43329, '<td valign="top">I cannot make a personification, either physical or emotional, out of this image.</td>', 'I cannot make a personification, either physical or emotional, out of this image.', '2005-10-16 17:37:28.000000', NULL, 1),
(1788017, 241788, 43329, '<td valign="top">I cannot make a personification, either physical or emotional, out of this image.</td>', 'I cannot make a personification, either physical or emotional, out of this image.', '2005-10-16 17:37:53.000000', NULL, 1),
(1788018, 242949, 40155, '<td valign="top">I wonder if it would have been possible to have the drips coming from the cheek rather than from the crown of the head?  Good idea.</td>', 'I wonder if it would have been possible to have the drips coming from the cheek rather than from the crown of the head?  Good idea.', '2005-10-16 17:38:05.000000', NULL, 1),
(1788019, 241362, 36231, '<td valign="top">This would have done better with utilizing all of the 640 pixels you are allowed. Your subject is very cute, however. Good luck!</td>', 'This would have done better with utilizing all of the 640 pixels you are allowed. Your subject is very cute, however. Good luck!', '2005-10-16 17:38:21.000000', NULL, 1),
(1788020, 240722, 36231, '<td valign="top">Very interesting.   The glow on the bottom right is a little distracting, but I like your crop. Good luck!</td>', 'Very interesting.   The glow on the bottom right is a little distracting, but I like your crop. Good luck!', '2005-10-16 17:38:58.000000', NULL, 1),
(1788022, 242734, 43329, '<td valign="top">I cannot make a personification, either physical or emotional, out of this image. I see an interesting "eye" shape, but that''s not enough to carry the feeling of a person communicating with me.</td>', 'I cannot make a personification, either physical or emotional, out of this image. I see an interesting "eye" shape, but that''s not enough to carry the feeling of a person communicating with me.', '2005-10-16 17:39:19.000000', NULL, 1),
(1788025, 241777, 43329, '<td valign="top">I cannot make a personification, either physical or emotional, out of this image.</td>', 'I cannot make a personification, either physical or emotional, out of this image.', '2005-10-16 17:39:54.000000', NULL, 1),
(1788027, 243093, 36231, '<td valign="top">Well .. this glass isn''t even half full! :)  Your lighting is a little harsh, and this could do well with a different crop - not so centered, and give the top some more breathing room. Nice concept, tho. Good luck!</td>', 'Well .. this glass isn''t even half full! :)  Your lighting is a little harsh, and this could do well with a different crop - not so centered, and give the top some more breathing room. Nice concept, tho. Good luck!', '2005-10-16 17:40:19.000000', NULL, 1),
(1788031, 243083, 43329, '<td valign="top">I cannot make a personification, either physical or emotional, out of this image. Nice photo of textures in dull light, but it doesn''t communicate a personal feeling to me. Sorry.</td>', 'I cannot make a personification, either physical or emotional, out of this image. Nice photo of textures in dull light, but it doesn''t communicate a personal feeling to me. Sorry.', '2005-10-16 17:41:25.000000', NULL, 1),
(1788037, 240722, 42198, '<td valign="top">Good idea. The mirror makes it more difficult to see the face. Also, that blown-out area bottom right is distracting.</td>', 'Good idea. The mirror makes it more difficult to see the face. Also, that blown-out area bottom right is distracting.', '2005-10-16 17:43:40.000000', NULL, 1),
(1788063, 241839, 42198, '<td valign="top">This is so wacky I like it!</td>', 'This is so wacky I like it!', '2005-10-16 18:01:07.000000', NULL, 1),
(1788079, 242353, 42198, '<td valign="top">This is just so wrong! - But entertaining. I like it. Not sure about the frame.</td>', 'This is just so wrong! - But entertaining. I like it. Not sure about the frame.', '2005-10-16 18:06:37.000000', NULL, 1),
(1788080, 241557, 42198, '<td valign="top">Okay, I can see it.... Interesting idea. It''s a bit of a stretch!</td>', 'Okay, I can see it.... Interesting idea. It''s a bit of a stretch!', '2005-10-16 18:07:55.000000', NULL, 1),
(1788081, 243103, 42198, '<td valign="top">Good idea, well executed. I like this one! Lighting is a bit strange, but I think it works.</td>', 'Good idea, well executed. I like this one! Lighting is a bit strange, but I think it works.', '2005-10-16 18:08:59.000000', NULL, 1),
(1788085, 242779, 42198, '<td valign="top">Pity about the reflections.</td>', 'Pity about the reflections.', '2005-10-16 18:09:51.000000', NULL, 1),
(1788086, 243023, 43191, '<td valign="top">Aww, poor little guy. Good shot.</td>', 'Aww, poor little guy. Good shot.', '2005-10-16 18:10:43.000000', NULL, 1),
(1788092, 242433, 43191, '<td valign="top">Is this something you created or were you out and about? Cute kid, may have worked better had been facing the tree talking to it or something.</td>', 'Is this something you created or were you out and about? Cute kid, may have worked better had been facing the tree talking to it or something.', '2005-10-16 18:12:58.000000', NULL, 1),
(1788093, 243023, 42198, '<td valign="top">Great idea - I love the lighting on this. Really nicely done.</td>', 'Great idea - I love the lighting on this. Really nicely done.', '2005-10-16 18:13:08.000000', NULL, 1),
(1788095, 242460, 43191, '<td valign="top">Works well.</td>', 'Works well.', '2005-10-16 18:13:44.000000', NULL, 1),
(1788100, 242903, 43191, '<td valign="top">Good idea, straighten it up and get rid of the door and drawers and it would work better IMO.</td>', 'Good idea, straighten it up and get rid of the door and drawers and it would work better IMO.', '2005-10-16 18:15:03.000000', NULL, 1),
(1788101, 242102, 42198, '<td valign="top">Nicely done! (No pun intended)</td>', 'Nicely done! (No pun intended)', '2005-10-16 18:15:21.000000', NULL, 1),
(1788103, 240722, 43191, '<td valign="top">Nice idea.</td>', 'Nice idea.', '2005-10-16 18:15:53.000000', NULL, 1),
(1788104, 242761, 43191, '<td valign="top">NIce idea the background is a little distracting though.</td>', 'NIce idea the background is a little distracting though.', '2005-10-16 18:16:56.000000', NULL, 1),
(1788105, 241090, 43191, '<td valign="top">What did you say to him??</td>', 'What did you say to him??', '2005-10-16 18:17:32.000000', NULL, 1),
(1788107, 241789, 42198, '<td valign="top">Wrong challenge?</td>', 'Wrong challenge?', '2005-10-16 18:17:53.000000', NULL, 1),
(1788108, 243099, 43191, '<td valign="top">Looks like they''ve fallen asleep on the job!</td>', 'Looks like they''ve fallen asleep on the job!', '2005-10-16 18:18:32.000000', NULL, 1),
(1788112, 241483, 40718, '<td valign="top">The Good:  Composition is nice with rule of thirds<br/>To work on: Challenge is met barely at most.  A little more light on the subject (the sword) would be nice.</td>', 'The Good:  Composition is nice with rule of thirdsTo work on: Challenge is met barely at most.  A little more light on the subject (the sword) would be nice.', '2005-10-16 18:22:19.000000', NULL, 1),
(1788115, 243099, 40718, '<td valign="top">The good: lighting and dynamic range are excellent.<br/>To work on: To me, the pipes actually seem less than alert since they are slumped over and "sleeping".  Am I the only one reading it like this?  I would have called it "The Slumbering Pipes".</td>', 'The good: lighting and dynamic range are excellent.To work on: To me, the pipes actually seem less than alert since they are slumped over and "sleeping".  Am I the only one reading it like this?  I would have called it "The Slumbering Pipes".', '2005-10-16 18:23:31.000000', NULL, 1),
(1788117, 242678, 40718, '<td valign="top">The good: cropping and composition.<br/>To work on: the upper bar is OOF.  The subject, as a whole, is uninspiring.  The color looks like it has that "flash" cast to it.</td>', 'The good: cropping and composition.To work on: the upper bar is OOF.  The subject, as a whole, is uninspiring.  The color looks like it has that "flash" cast to it.', '2005-10-16 18:24:59.000000', NULL, 1),
(1788120, 242685, 40718, '<td valign="top">The good: focus is spot on.  The blur of the water is an excellent effect.<br/>To work on: This is an entry where I would not have come up with the idea without the title.  Perhaps a little more centering (but not totally centered, I like the placement, just a tad less extreme).</td>', 'The good: focus is spot on.  The blur of the water is an excellent effect.To work on: This is an entry where I would not have come up with the idea without the title.  Perhaps a little more centering (but not totally centered, I like the placement, just a tad less extreme).', '2005-10-16 18:26:22.000000', NULL, 1),
(1788122, 243026, 40718, '<td valign="top">The good: creative title and idea.<br/>To work on:  Pictures like this wind up being unexciting without something in the foreground, even if it isn''t the main subject.  The lighting is perhaps a bit too dark.</td>', 'The good: creative title and idea.To work on:  Pictures like this wind up being unexciting without something in the foreground, even if it isn''t the main subject.  The lighting is perhaps a bit too dark.', '2005-10-16 18:27:31.000000', NULL, 1),
(1788123, 242083, 40718, '<td valign="top">The good: composition is excellent.<br/>To work on: The focus looks off on the right.  The challenge idea is barely met, IMO.</td>', 'The good: composition is excellent.To work on: The focus looks off on the right.  The challenge idea is barely met, IMO.', '2005-10-16 18:28:22.000000', NULL, 1),
(1788124, 240853, 40718, '<td valign="top">The good: nice tight crop.<br/>To work on:  the picture has a color cast to it.  I''m not so fond of the "constucted face" entries as a whole.</td>', 'The good: nice tight crop.To work on:  the picture has a color cast to it.  I''m not so fond of the "constucted face" entries as a whole.', '2005-10-16 18:29:25.000000', NULL, 1),
(1788126, 241475, 40718, '<td valign="top">The good: interesting subject<br/>To work on: not quite enough for me to be able to tell what it is.  I''m not sure what I''m looking at.  I also wish you had used an adjective for the "personification" like "the rushed woodman".  It''s possible your camera autofocused on the front tree rather than the subject. ?</td>', 'The good: interesting subjectTo work on: not quite enough for me to be able to tell what it is.  I''m not sure what I''m looking at.  I also wish you had used an adjective for the "personification" like "the rushed woodman".  It''s possible your camera autofocused on the front tree rather than the subject. ?', '2005-10-16 18:30:57.000000', NULL, 1),
(1788127, 242823, 40718, '<td valign="top">The good: nice composition.  Centering works here.<br/>To work on: The picture is overexposed with the upper panel blown out.  The face is a bit difficult to see and I wish it had an "adjective" so we could really go for a personified characteristic or emotion. "The stoic laundry man"</td>', 'The good: nice composition.  Centering works here.To work on: The picture is overexposed with the upper panel blown out.  The face is a bit difficult to see and I wish it had an "adjective" so we could really go for a personified characteristic or emotion. "The stoic laundry man"', '2005-10-16 18:32:23.000000', NULL, 1),
(1788130, 242734, 40718, '<td valign="top">The good: composition is excellent, focus is spot on.<br/>To work on:  I was wishing for an adjective with the face for the "personification".  "The bored tree" or the like.  This shows me the face, but doesn''t give me much else to work with.</td>', 'The good: composition is excellent, focus is spot on.To work on:  I was wishing for an adjective with the face for the "personification".  "The bored tree" or the like.  This shows me the face, but doesn''t give me much else to work with.', '2005-10-16 18:33:26.000000', NULL, 1),
(1788133, 243022, 40718, '<td valign="top">The good: excellent idea for personification.  The selective desat is nice.<br/>To work on:   Is enough in focus?  Also I would not have guessed what you were going for without the title.  Once I read it, I can see it, but not before.</td>', 'The good: excellent idea for personification.  The selective desat is nice.To work on:   Is enough in focus?  Also I would not have guessed what you were going for without the title.  Once I read it, I can see it, but not before.', '2005-10-16 18:35:20.000000', NULL, 1),
(1788134, 242843, 40718, '<td valign="top">Statues and figurines did not meet the challenge in my opinion.  Otherwise, nice composition, although there appears to be a slight color cast.</td>', 'Statues and figurines did not meet the challenge in my opinion.  Otherwise, nice composition, although there appears to be a slight color cast.', '2005-10-16 18:36:32.000000', NULL, 1),
(1788138, 242700, 40718, '<td valign="top">It''s hard for me to decide if a stuffed animal is a good subject for an inanimate object.  At first I had decided no and had this as a 2, but I think in the end, it does qualify.  The composition and lighting are very nice.  I''m going to bump this to a 6.</td>', 'It''s hard for me to decide if a stuffed animal is a good subject for an inanimate object.  At first I had decided no and had this as a 2, but I think in the end, it does qualify.  The composition and lighting are very nice.  I''m going to bump this to a 6.', '2005-10-16 18:37:58.000000', NULL, 1),
(1788139, 243086, 40718, '<td valign="top">Not an inanimate object.</td>', 'Not an inanimate object.', '2005-10-16 18:38:14.000000', NULL, 1),
(1788141, 242982, 40718, '<td valign="top">Not an inanimate object.</td>', 'Not an inanimate object.', '2005-10-16 18:38:23.000000', NULL, 1),
(1788143, 243149, 40718, '<td valign="top">Statues and figurines did not meet the challenge in my opinion.  It''s a cute idea though.</td>', 'Statues and figurines did not meet the challenge in my opinion.  It''s a cute idea though.', '2005-10-16 18:38:36.000000', NULL, 1),
