(1788769, 241672, 33947, '<td valign="top">Super lighting. Very sharp and clear. Like it a lot. 10</td>', 'Super lighting. Very sharp and clear. Like it a lot. 10', '2005-10-16 23:40:02.000000', NULL, 1),
(1788816, 241002, 45021, '<td valign="top">Great shot, unique and fits challenge perfectly.</td>', 'Great shot, unique and fits challenge perfectly.', '2005-10-16 23:56:20.000000', NULL, 1),
(1788823, 240845, 45021, '<td valign="top">Well thought out shot.  Don''t know about the subject he is looking at or the dark space on the right.  I tried to do a similar shot and had problem getting lighting right as well.  Despite this it is still a good shot.</td>', 'Well thought out shot.  Don''t know about the subject he is looking at or the dark space on the right.  I tried to do a similar shot and had problem getting lighting right as well.  Despite this it is still a good shot.', '2005-10-16 23:58:20.000000', NULL, 1),
(1788825, 243023, 45021, '<td valign="top">Nicely done, although I find the desk a little distracting, I would have cropped more out, none the less a great shot.</td>', 'Nicely done, although I find the desk a little distracting, I would have cropped more out, none the less a great shot.', '2005-10-16 23:59:33.000000', NULL, 1),
(1788827, 242857, 45021, '<td valign="top">Well spotted and shot. A very unique shot.</td>', 'Well spotted and shot. A very unique shot.', '2005-10-17 00:00:20.000000', NULL, 1),
