(1790372, 242086, 6667, '<td valign="top">Wowa!  What a great enry for he current reflections challenge.  Never- the -less, BOL here. Nicely done.</td>', 'Wowa!  What a great enry for he current reflections challenge.  Never- the -less, BOL here. Nicely done.', '2005-10-17 15:48:41.000000', NULL, 1),
(1790373, 243023, 36231, '<td valign="top">One of my favorites.  Definitely a top 10.  Not only do you convey through the seperation, but you used different colors. Great job and good luck! :)</td>', 'One of my favorites.  Definitely a top 10.  Not only do you convey through the seperation, but you used different colors. Great job and good luck! :)', '2005-10-17 15:48:49.000000', NULL, 1),
(1790382, 243002, 36231, '<td valign="top">Wow ... great capture.  Nice portrayal and use of empty space.  I got it immediately when I opened the photo. Hope this is a top 10, as it is one of my favorites. Good luck! :)</td>', 'Wow ... great capture.  Nice portrayal and use of empty space.  I got it immediately when I opened the photo. Hope this is a top 10, as it is one of my favorites. Good luck! :)', '2005-10-17 15:51:31.000000', NULL, 1),
