(1792783, 242981, 42005, '<td valign="top">Interesting and effective use of part of a vessel.  Good use of light. 8</td>', 'Interesting and effective use of part of a vessel.  Good use of light. 8', '2005-10-18 14:02:08.000000', NULL, 1),
