(1792794, 241373, 42005, '<td valign="top">Quite effective use of the openers.  Good lighting. 8</td>', 'Quite effective use of the openers.  Good lighting. 8', '2005-10-18 14:05:10.000000', NULL, 1),
(1792812, 242354, 42005, '<td valign="top">Wow  This belongs on a mystery book cover.  Great find.  Thank you for sharing.</td>', 'Wow  This belongs on a mystery book cover.  Great find.  Thank you for sharing.', '2005-10-18 14:11:50.000000', NULL, 1),
