(1792823, 240934, 42005, '<td valign="top">Very interesting.  Great use of starkness to also reflect the personification of<br/>emotion.  9</td>', 'Very interesting.  Great use of starkness to also reflect the personification ofemotion.  9', '2005-10-18 14:14:09.000000', NULL, 1),
(1792826, 242705, 42005, '<td valign="top">Great sharp picture. I think I might have named it "Whipped."  8</td>', 'Great sharp picture. I think I might have named it "Whipped."  8', '2005-10-18 14:15:05.000000', NULL, 1),
(1792845, 242107, 40371, '<td valign="top">Very interesting perspective.  I love it because I actually had to think about it.</td>', 'Very interesting perspective.  I love it because I actually had to think about it.', '2005-10-18 14:20:38.000000', NULL, 1),
(1792847, 241993, 42005, '<td valign="top">Clever.  The lighting is good and the color marvelous.  I found the chop sticks<br/>distracting.  It reminded me of a baby shower I went to and each team had to make <br/>a baby for the mother to be out of vegetables in their whole form.  Love the ears! 8</td>', 'Clever.  The lighting is good and the color marvelous.  I found the chop sticksdistracting.  It reminded me of a baby shower I went to and each team had to make a baby for the mother to be out of vegetables in their whole form.  Love the ears! 8', '2005-10-18 14:21:08.000000', NULL, 1),
(1792850, 242242, 42005, '<td valign="top">I like the title.  Because we can see different things in it for sure and I think it is<br/>best left to the imagination of the viewer.  Great! 10  Dare we have a forum to <br/>name it after you win a ribbon? 10</td>', 'I like the title.  Because we can see different things in it for sure and I think it isbest left to the imagination of the viewer.  Great! 10  Dare we have a forum to name it after you win a ribbon? 10', '2005-10-18 14:21:26.000000', NULL, 1),
(1792857, 242879, 40371, '<td valign="top">I''m sure you were trying to make this blurry-kinda an artsy effect?</td>', 'I''m sure you were trying to make this blurry-kinda an artsy effect?', '2005-10-18 14:24:23.000000', NULL, 1),
(1792863, 241002, 3818, '<td valign="top">Perfect title, beautifully photographed and presented. This one should do very well...Congrats!</td>', 'Perfect title, beautifully photographed and presented. This one should do very well...Congrats!', '2005-10-18 14:26:02.000000', NULL, 1),
(1792872, 242626, 40371, '<td valign="top">I think I may have liked this better if the background was more "clinical"-not so bright but this is a spectacular idea!</td>', 'I think I may have liked this better if the background was more "clinical"-not so bright but this is a spectacular idea!', '2005-10-18 14:29:06.000000', NULL, 1),
(1792881, 242107, 3818, '<td valign="top">Interesting concept...and how you did it must have taken a lot of thought and preparation and hard work. The exposure is absolutely perfect, the focus excellent. My only nit is that the composition seems a bit unbalanced. I think it would have been better to include some more of the dark area on the left to more equally match the area on the right, or crop some off the right. All in all, a very worthy effort!</td>', 'Interesting concept...and how you did it must have taken a lot of thought and preparation and hard work. The exposure is absolutely perfect, the focus excellent. My only nit is that the composition seems a bit unbalanced. I think it would have been better to include some more of the dark area on the left to more equally match the area on the right, or crop some off the right. All in all, a very worthy effort!', '2005-10-18 14:31:53.000000', NULL, 1),
(1792885, 243136, 40371, '<td valign="top">Excellent idea-wondering how long you had to watch and fan the flames before you got the desired effect.</td>', 'Excellent idea-wondering how long you had to watch and fan the flames before you got the desired effect.', '2005-10-18 14:32:45.000000', NULL, 1),
(1792889, 242355, 3818, '<td valign="top">I like this! Don''t know if it says "scuba" to me, but it does look rather oddly human-like! Rates pretty high on the cuteness and humor scale for me, and the black and white treatment works well here. Nice one~ ;)</td>', 'I like this! Don''t know if it says "scuba" to me, but it does look rather oddly human-like! Rates pretty high on the cuteness and humor scale for me, and the black and white treatment works well here. Nice one~ ;)', '2005-10-18 14:35:03.000000', NULL, 1),
(1792890, 242507, 40371, '<td valign="top">I''m having a really hard time seeing what you are trying to portray</td>', 'I''m having a really hard time seeing what you are trying to portray', '2005-10-18 14:36:32.000000', NULL, 1),
(1792909, 242354, 3818, '<td valign="top">Oh, this is just weirdly enjoyable, isn''t it? Must have taken years to get the tree shaped like this (from cuts? grafts? Strange occultic practices???). Good comp, B&amp;W makes for an interesting presentation (though I see some purple fringing around some branches where the lighter sky area comes through). Exposure on the tree is very good, bringing out the right amount of detail there...just wish you''d moved a bit more to the right to get rid of that distracting bright (overexposed) sky. But overall, an interesting and very different shot. I like it!</td>', 'Oh, this is just weirdly enjoyable, isn''t it? Must have taken years to get the tree shaped like this (from cuts? grafts? Strange occultic practices???). Good comp, B&W makes for an interesting presentation (though I see some purple fringing around some branches where the lighter sky area comes through). Exposure on the tree is very good, bringing out the right amount of detail there...just wish you''d moved a bit more to the right to get rid of that distracting bright (overexposed) sky. But overall, an interesting and very different shot. I like it!', '2005-10-18 14:43:36.000000', NULL, 1),
(1792913, 241504, 3818, '<td valign="top">And a rugged fellow he is, too! ;)</td>', 'And a rugged fellow he is, too! ;)', '2005-10-18 14:44:34.000000', NULL, 1),
(1792919, 243023, 3818, '<td valign="top">Clever, clever, clever!!! This one should get a lot of votes~ :D</td>', 'Clever, clever, clever!!! This one should get a lot of votes~ :D', '2005-10-18 14:46:16.000000', NULL, 1),
(1792929, 242374, 3818, '<td valign="top">Simple, powerful, well photographed~</td>', 'Simple, powerful, well photographed~', '2005-10-18 14:48:42.000000', NULL, 1),
(1792934, 242703, 40371, '<td valign="top">Excellent title.</td>', 'Excellent title.', '2005-10-18 14:49:58.000000', NULL, 1),
(1792940, 242974, 40371, '<td valign="top">For some reason this reminds me of the Sneeches :)</td>', 'For some reason this reminds me of the Sneeches :)', '2005-10-18 14:52:43.000000', NULL, 1),
(1792943, 241359, 3818, '<td valign="top">LOL! Thanks for my morning chuckle (out loud, even!). Good eye, great concept, well done!!! ~ :D</td>', 'LOL! Thanks for my morning chuckle (out loud, even!). Good eye, great concept, well done!!! ~ :D', '2005-10-18 14:53:18.000000', NULL, 1),
(1792950, 241982, 40371, '<td valign="top">I love your title-it''s very Gary Larson.  I would have liked the pic better if it didn''t look so grainy.</td>', 'I love your title-it''s very Gary Larson.  I would have liked the pic better if it didn''t look so grainy.', '2005-10-18 14:56:12.000000', NULL, 1),
(1792954, 242726, 3818, '<td valign="top">Cheesy, but cute! The one on the left reminds me of Kermit the frog...sort of...  Anyone for a bit of Veggie Tales? Seems a bit tilted and the texture of the backgound is a wee bit distracting (if it was mine, I''d want to straighten it up and blow out the background to pure white in editing)~</td>', 'Cheesy, but cute! The one on the left reminds me of Kermit the frog...sort of...  Anyone for a bit of Veggie Tales? Seems a bit tilted and the texture of the backgound is a wee bit distracting (if it was mine, I''d want to straighten it up and blow out the background to pure white in editing)~', '2005-10-18 14:57:42.000000', NULL, 1),
(1792959, 242255, 3818, '<td valign="top">I think I know this tree (and have a similar shot of one like it!!!). Looks like one of the giant redwoods in Sequoia Nat''l Park. Not sure about personification here...but that''s one heck of a tall looking tree! :)</td>', 'I think I know this tree (and have a similar shot of one like it!!!). Looks like one of the giant redwoods in Sequoia Nat''l Park. Not sure about personification here...but that''s one heck of a tall looking tree! :)', '2005-10-18 14:59:54.000000', NULL, 1),
(1792967, 240893, 3818, '<td valign="top">I almost missed the face because I was looking for it in the little droplet at the top...doh! Great capture and if folks take the time to really look at this (the thumbnail doesn''t do it justice), it should do well~</td>', 'I almost missed the face because I was looking for it in the little droplet at the top...doh! Great capture and if folks take the time to really look at this (the thumbnail doesn''t do it justice), it should do well~', '2005-10-18 15:03:18.000000', NULL, 1),
(1792978, 242758, 3818, '<td valign="top">Maybe I''m missing something here (or I''m just too thick to get it), so I''m hoping a further explanation by the photographer will help. Why is the hydrant so overexposed and what is the personification represented here? Inquiring minds want to know...especially somewhat dull minds like mine!</td>', 'Maybe I''m missing something here (or I''m just too thick to get it), so I''m hoping a further explanation by the photographer will help. Why is the hydrant so overexposed and what is the personification represented here? Inquiring minds want to know...especially somewhat dull minds like mine!', '2005-10-18 15:06:45.000000', NULL, 1),
(1792985, 242602, 3818, '<td valign="top">I love the way the upper flower is hugging the stem so it doesn''t fall down while "talking" to the flower on the left. Cute...a little busy with the tilted purple *striped* background, but all in all, a very appealing shot~</td>', 'I love the way the upper flower is hugging the stem so it doesn''t fall down while "talking" to the flower on the left. Cute...a little busy with the tilted purple *striped* background, but all in all, a very appealing shot~', '2005-10-18 15:09:21.000000', NULL, 1),
(1792992, 240853, 3818, '<td valign="top">Ewwwww....this, um, kinda grosses me out! Why the oddly hazy look to the shot? Good concept, but that glob of goo makes me feel a bit sick to my stomach...ick! ;)</td>', 'Ewwwww....this, um, kinda grosses me out! Why the oddly hazy look to the shot? Good concept, but that glob of goo makes me feel a bit sick to my stomach...ick! ;)', '2005-10-18 15:11:10.000000', NULL, 1),
(1792997, 243165, 3818, '<td valign="top">A well done, powerfully emotive photo...just don''t feel it fits the challenge all that well since it actually has a person rather than a human-like inanimate object.</td>', 'A well done, powerfully emotive photo...just don''t feel it fits the challenge all that well since it actually has a person rather than a human-like inanimate object.', '2005-10-18 15:13:50.000000', NULL, 1),
(1793000, 242308, 3818, '<td valign="top">Simple, cute, to the point...great job!</td>', 'Simple, cute, to the point...great job!', '2005-10-18 15:14:16.000000', NULL, 1),
(1793005, 241475, 3818, '<td valign="top">Ouch!!! I would have called this something like "Persecution" or "Upon Pain of Death" or "Torture". Interesting sculpture?</td>', 'Ouch!!! I would have called this something like "Persecution" or "Upon Pain of Death" or "Torture". Interesting sculpture?', '2005-10-18 15:15:59.000000', NULL, 1),
(1793008, 242949, 40371, '<td valign="top">It''s not personification if the stone was carved to look like a person.</td>', 'It''s not personification if the stone was carved to look like a person.', '2005-10-18 15:17:43.000000', NULL, 1),
(1793011, 243023, 40371, '<td valign="top">Excellent, the black sheep...er lamp.</td>', 'Excellent, the black sheep...er lamp.', '2005-10-18 15:19:01.000000', NULL, 1),
(1793012, 243111, 40371, '<td valign="top">Love the smoke!</td>', 'Love the smoke!', '2005-10-18 15:19:22.000000', NULL, 1),
(1793014, 242876, 3818, '<td valign="top">What an interesting building! Looks Chinese, perhaps? Could be a stronger composition...the bottom third tends to distract from the shot, but the hair eyes and nose of this elderly "grandma" house are quite evident.</td>', 'What an interesting building! Looks Chinese, perhaps? Could be a stronger composition...the bottom third tends to distract from the shot, but the hair eyes and nose of this elderly "grandma" house are quite evident.', '2005-10-18 15:19:59.000000', NULL, 1),
(1793015, 242870, 40371, '<td valign="top">This gets me on so many levels.  So simple and yet it stirs up so much emotion.</td>', 'This gets me on so many levels.  So simple and yet it stirs up so much emotion.', '2005-10-18 15:20:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1793024, 242980, 30817, '<td valign="top">touching shot ... a bit of poetry.</td>', 'touching shot ... a bit of poetry.', '2005-10-18 15:25:05.000000', NULL, 1),
(1793027, 241776, 30817, '<td valign="top">...or a lion''s head.  Great find!</td>', '...or a lion''s head.  Great find!', '2005-10-18 15:26:10.000000', NULL, 1),
(1793029, 242536, 3818, '<td valign="top">A little contrived, but shows some thought was put into this. Not sure two soda bottles in a natural setting makes a lot of sense to me... Rocks might have been a better choice. The ocean scene is outstanding...but the bottles remind me more of the way folks trash nature than of love. Two champagne glasses might have worked a little better...or two pair of shoes (making you think the people were off wading). Hard to decide how to score this one...a great shot in so many aspects, but...</td>', 'A little contrived, but shows some thought was put into this. Not sure two soda bottles in a natural setting makes a lot of sense to me... Rocks might have been a better choice. The ocean scene is outstanding...but the bottles remind me more of the way folks trash nature than of love. Two champagne glasses might have worked a little better...or two pair of shoes (making you think the people were off wading). Hard to decide how to score this one...a great shot in so many aspects, but...', '2005-10-18 15:26:39.000000', NULL, 1),
(1793032, 242543, 40977, '<td valign="top">Great Job --10--<br/></td>', 'Great Job --10--', '2005-10-18 15:28:27.000000', NULL, 1),
