(1793045, 241381, 40371, '<td valign="top">Excellent title!</td>', 'Excellent title!', '2005-10-18 15:31:48.000000', NULL, 1),
(1793047, 242354, 40977, '<td valign="top">Oh My - great job on this shot.  great focus and desat really works with this image. An image that would spark the imagination of any child -- well adult for that matter.  Well done --9--</td>', 'Oh My - great job on this shot.  great focus and desat really works with this image. An image that would spark the imagination of any child -- well adult for that matter.  Well done --9--', '2005-10-18 15:32:14.000000', NULL, 1),
