(1793050, 243136, 40977, '<td valign="top">LOVE IT!!!  True personification.  Great catch --8--</td>', 'LOVE IT!!!  True personification.  Great catch --8--', '2005-10-18 15:32:54.000000', NULL, 1),
(1793052, 241672, 40371, '<td valign="top">Lovin'' this idea.</td>', 'Lovin'' this idea.', '2005-10-18 15:33:17.000000', NULL, 1),
(1793054, 241135, 40977, '<td valign="top">Such a flirt --- I think he is winking at me.  Great job on focus, clarity and composition.   Really well done --9--</td>', 'Such a flirt --- I think he is winking at me.  Great job on focus, clarity and composition.   Really well done --9--', '2005-10-18 15:34:08.000000', NULL, 1),
(1793055, 243075, 30817, '<td valign="top">What an incredible tree!  Would have scored you higher if you could have isolated it a bit more.  The house front does not detract as much as the roof and smaller trunk to the right of the subject and the diagonal branch in the UL corner.</td>', 'What an incredible tree!  Would have scored you higher if you could have isolated it a bit more.  The house front does not detract as much as the roof and smaller trunk to the right of the subject and the diagonal branch in the UL corner.', '2005-10-18 15:34:33.000000', NULL, 1),
(1793057, 241775, 40977, '<td valign="top">Upside down??  I love the title and the image is spot on.  Great colors and clarity --8--</td>', 'Upside down??  I love the title and the image is spot on.  Great colors and clarity --8--', '2005-10-18 15:35:02.000000', NULL, 1),
