INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1794483, 242879, 3818, '<td valign="top">Thanks for all your comments! Guess this pic didn''t quite convey what I was hoping for (the ball fleeing for it''s very "life" but about to be caught anyhow, therefore "No Escape"). The slow shutter was purposeful, hoping the feeling of blurred movement would heighten the tension...but alas, the attempt didn''t work. Oh well...maybe next challenge, eh? :)</td>', 'Thanks for all your comments! Guess this pic didn''t quite convey what I was hoping for (the ball fleeing for it''s very "life" but about to be caught anyhow, therefore "No Escape"). The slow shutter was purposeful, hoping the feeling of blurred movement would heighten the tension...but alas, the attempt didn''t work. Oh well...maybe next challenge, eh? :)', '2005-10-19 02:30:09.000000', NULL, 0),
